class Solution {
public:
    vector<vector<int>> averageHeightOfBuildings(vector<vector<int>>& buildings) {
        map<int, pair<long long, int>> events;
        for (const auto& b : buildings) {
            events[b[0]].first += b[2];
            events[b[0]].second += 1;
            events[b[1]].first -= b[2];
            events[b[1]].second -= 1;
        }
        vector<vector<int>> res;
        long long curr_h = 0;
        int curr_cnt = 0;
        int prev_pos = -1;
        for (const auto& [p, delta] : events) {
            if (prev_pos != -1 && curr_cnt > 0) {
                int avg = curr_h / curr_cnt;
                if (!res.empty() && res.back()[1] == prev_pos && res.back()[2] == avg) {
                    res.back()[1] = p;
                } else {
                    res.push_back({prev_pos, p, avg});
                }
            }
            curr_h += delta.first;
            curr_cnt += delta.second;
            prev_pos = p;
        }
        return res;
    }
};

class Solution {
    public int[][] averageHeightOfBuildings(int[][] buildings) {
        TreeMap<Integer, long[]> events = new TreeMap<>();
        for (int[] b : buildings) {
            events.computeIfAbsent(b[0], k -> new long[2])[0] += b[2];
            events.get(b[0])[1] += 1;
            events.computeIfAbsent(b[1], k -> new long[2])[0] -= b[2];
            events.get(b[1])[1] -= 1;
        }
        List<int[]> res = new ArrayList<>();
        long currH = 0;
        int currCnt = 0;
        int prevPos = -1;
        for (Map.Entry<Integer, long[]> entry : events.entrySet()) {
            int p = entry.getKey();
            if (prevPos != -1 && currCnt > 0) {
                int avg = (int)(currH / currCnt);
                if (!res.isEmpty() && res.get(res.size() - 1)[1] == prevPos && res.get(res.size() - 1)[2] == avg) {
                    res.get(res.size() - 1)[1] = p;
                } else {
                    res.add(new int[]{prevPos, p, avg});
                }
            }
            currH += entry.getValue()[0];
            currCnt += (int)entry.getValue()[1];
            prevPos = p;
        }
        return res.toArray(new int[res.size()][]);
    }
}

var averageHeightOfBuildings = function(buildings) {
  const events = new Map();
  for (const [s, e, h] of buildings) {
    if (!events.has(s)) events.set(s, [0, 0]);
    if (!events.has(e)) events.set(e, [0, 0]);
    events.get(s)[0] += h;
    events.get(s)[1] += 1;
    events.get(e)[0] -= h;
    events.get(e)[1] -= 1;
  }
  const pts = Array.from(events.keys()).sort((a, b) => a - b);
  const res = [];
  let currH = 0;
  let currCnt = 0;
  let prevPos = null;

  for (const p of pts) {
    if (prevPos !== null && currCnt > 0) {
      const avg = Math.floor(currH / currCnt);
      if (res.length > 0 && res[res.length - 1][1] === prevPos && res[res.length - 1][2] === avg) {
        res[res.length - 1][1] = p;
      } else {
        res.push([prevPos, p, avg]);
      }
    }
    const [dh, dc] = events.get(p);
    currH += dh;
    currCnt += dc;
    prevPos = p;
  }
  return res;
};
